import { mergeProps, splitProps } from '@benosjs/dom'
import type { JSX } from '@benosjs/dom'

export type InputSize = 'sm' | 'md' | 'lg'
export type InputType = 'email' | 'number' | 'password' | 'search' | 'tel' | 'text' | 'url'

export type InputProps = Omit<JSX.IntrinsicElements['input'], 'class' | 'ref' | 'type'> & {
  id?: string
  class?: string
  size?: InputSize
  type?: InputType
  invalid?: boolean
  ref?: (element: HTMLInputElement) => void
}

export function Input(props: InputProps): JSX.Element {
  const merged = mergeProps({ type: 'text' as const, size: 'md' as const, invalid: false }, props)
  const [local, native] = splitProps(merged, [
    'size',
    'class',
    'invalid',
    'ref',
    'children',
    'aria-invalid',
  ] as const)
  const ariaInvalid =
    local.invalid || local['aria-invalid'] === true || local['aria-invalid'] === 'true'
      ? 'true'
      : (local['aria-invalid'] ?? 'false')
  const ref = (element: HTMLInputElement) => local.ref?.(element)

  return (
    <input
      {...native}
      class={['benos-input', 'benos-input--' + local.size, local.class].filter(Boolean).join(' ')}
      aria-invalid={ariaInvalid}
      data-invalid={ariaInvalid === 'true' ? 'true' : 'false'}
      ref={ref}
    />
  )
}

.benos-input {
  background: var(--benos-color-surface);
  border: 1px solid var(--benos-color-border);
  box-sizing: border-box;
  border-radius: var(--benos-radius-md);
  color: var(--benos-color-text);
  display: block;
  font: inherit;
  inline-size: 100%;
  min-inline-size: 0;
}

.benos-input--sm {
  block-size: 2rem;
  padding-inline: var(--benos-space-2);
}

.benos-input--md {
  block-size: 2.5rem;
  padding-inline: var(--benos-space-3);
}

.benos-input--lg {
  block-size: 3rem;
  padding-inline: var(--benos-space-4);
}

.benos-input::placeholder {
  color: var(--benos-color-text-muted);
  opacity: 1;
}

.benos-input:focus-visible {
  border-color: var(--benos-color-focus);
  outline: 3px solid var(--benos-color-focus);
  outline-offset: 2px;
}

.benos-input[aria-invalid='true'] {
  border-color: var(--benos-color-danger);
}

.benos-input:disabled {
  background: var(--benos-color-canvas);
  color: var(--benos-color-text-muted);
  cursor: not-allowed;
}
